function validate([nums, k]) {
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each value of nums is an integer from 1 to 100000.';
  if (!Number.isInteger(k) || k < 1 || k > 1e15) return 'k is an integer from 1 to 10^15.';
  return null;
}

