function countSubarrays(nums, k) {
  let total = 0;
  for (let start = 0; start < nums.length; start++) {
    for (let end = start; end < nums.length; end++) {
      let s = 0;
      for (let i = start; i <= end; i++) s += nums[i];
      if (s * (end - start + 1) < k) total++;
    }
  }
  return total;
}

